export function createMappedTestRace(id){
 const data=tracks[id==='laguna-seca'?'weathertech-raceway':id];if(!data)return null;
 const race=structuredClone(data.race),t=data.terrain,raw=atob(t.heights);
 const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)),view=new DataView(bytes.buffer);
 const cells={};for(let y=0;y<t.height;y++)for(let x=0;x<t.width;x++)cells[(x+t.minX)+','+(y+t.minY)]={tileId:race.road.tileMap.defaultTileId,elevation:view.getInt32((y*t.width+x)*4,true)/1000};
 race.road.tileMap.cells=cells;return race;
}
